  "Similar winning runs": { eng: "Similar winning runs", deu: "Ähnliche siegreiche Läufe", esp: "Partidas ganadoras similares", fra: "Parties gagnantes similaires", ita: "Partite vincenti simili", jpn: "似た勝利ラン", kor: "비슷한 승리 런", pol: "Podobne wygrane rozgrywki", ptb: "Partidas vencedoras semelhantes", rus: "Похожие победные забеги", spa: "Partidas ganadoras similares", tha: "การเล่นที่ชนะที่คล้ายกัน", tur: "Benzer kazanan koşular", zhs: "相似的胜利对局", zht: "相似的勝利對局" },
  "The closest winning decks to this one, by cards and relics.": { eng: "The closest winning decks to this one, by cards and relics.", deu: "Die diesem am nächsten kommenden siegreichen Decks, nach Karten und Relikten.", esp: "Los mazos ganadores más parecidos a este, por cartas y reliquias.", fra: "Les decks gagnants les plus proches de celui-ci, par cartes et reliques.", ita: "I mazzi vincenti più simili a questo, per carte e reliquie.", jpn: "カードとレリックが最も近い勝利デッキ。", kor: "카드와 유물 기준으로 가장 가까운 승리 덱입니다.", pol: "Wygrane talie najbardziej zbliżone do tej, według kart i reliktów.", ptb: "Os baralhos vencedores mais próximos deste, por cartas e relíquias.", rus: "Ближайшие к этой победные колоды по картам и реликвиям.", spa: "Los mazos ganadores más parecidos a este, por cartas y reliquias.", tha: "เด็คที่ชนะซึ่งใกล้เคียงกับเด็คนี้ที่สุด ตามการ์ดและเรลิก", tur: "Kartlara ve kalıntılara göre buna en yakın kazanan desteler.", zhs: "按卡牌与遗物计算，与此最接近的胜利卡组。", zht: "按卡牌與遺物計算，與此最接近的勝利卡組。" },
  "Winners with decks like this also took": { eng: "Winners with decks like this also took", deu: "Sieger mit ähnlichen Decks nahmen auch", esp: "Los ganadores con mazos así también tomaron", fra: "Les vainqueurs avec des decks similaires ont aussi pris", ita: "I vincitori con mazzi simili hanno preso anche", jpn: "似たデッキで勝利したプレイヤーが他に取ったもの", kor: "비슷한 덱으로 승리한 플레이어가 함께 선택한 것", pol: "Zwycięzcy z takimi taliami brali też", ptb: "Vencedores com baralhos assim também pegaram", rus: "Победители с похожими колодами также брали", spa: "Los ganadores con mazos así también tomaron", tha: "ผู้ชนะที่มีเด็คแบบนี้ยังเลือก", tur: "Böyle destelerle kazananlar ayrıca şunları aldı", zhs: "使用类似卡组获胜的玩家还选取了", zht: "使用類似卡組獲勝的玩家還選取了" },
