  "Rarity, pool, description, shop price": { eng: "Rarity, pool, description, shop price", deu: "Seltenheit, Pool, Beschreibung, Shop-Preis", esp: "Rareza, pool, descripción, precio en tienda", fra: "Rareté, pool, description, prix en boutique", ita: "Rarità, pool, descrizione, prezzo al negozio", jpn: "レアリティ、プール、説明、ショップ価格", kor: "희귀도, 풀, 설명, 상점 가격", pol: "Rzadkość, pula, opis, cena w sklepie", ptb: "Raridade, pool, descrição, preço na loja", rus: "Редкость, пул, описание, цена в магазине", spa: "Rareza, pool, descripción, precio en tienda", tha: "ความหายาก พูล คำอธิบาย ราคาร้านค้า", tur: "Nadirlik, havuz, açıklama, dükkan fiyatı", zhs: "稀有度、卡池、描述、商店价格", zht: "稀有度、卡池、描述、商店價格" },
  "HP ranges, moves, innate powers, attack patterns": { eng: "HP ranges, moves, innate powers, attack patterns", deu: "LP-Bereiche, Aktionen, angeborene Kräfte, Angriffsmuster", esp: "Rangos de PV, movimientos, poderes innatos, patrones de ataque", fra: "Plages de PV, actions, pouvoirs innés, schémas d'attaque", ita: "Intervalli di PV, mosse, poteri innati, schemi d'attacco", jpn: "HP範囲、行動、固有パワー、攻撃パターン", kor: "HP 범위, 행동, 고유 파워, 공격 패턴", pol: "Zakresy PŻ, ruchy, wrodzone moce, wzorce ataków", ptb: "Faixas de HP, ações, poderes inatos, padrões de ataque", rus: "Диапазоны HP, действия, врождённые силы, схемы атак", spa: "Rangos de PV, movimientos, poderes innatos, patrones de ataque", tha: "ช่วง HP ท่าโจมตี พลังติดตัว รูปแบบการโจมตี", tur: "HP aralıkları, hareketler, doğuştan güçler, saldırı kalıpları", zhs: "生命范围、行动、固有能力、攻击模式", zht: "生命範圍、行動、固有能力、攻擊模式" },
  "Rarity, pool, resolved description": { eng: "Rarity, pool, resolved description", deu: "Seltenheit, Pool, aufgelöste Beschreibung", esp: "Rareza, pool, descripción resuelta", fra: "Rareté, pool, description résolue", ita: "Rarità, pool, descrizione risolta", jpn: "レアリティ、プール、数値展開済みの説明", kor: "희귀도, 풀, 수치가 반영된 설명", pol: "Rzadkość, pula, rozwinięty opis", ptb: "Raridade, pool, descrição resolvida", rus: "Редкость, пул, описание с подставленными значениями", spa: "Rareza, pool, descripción resuelta", tha: "ความหายาก พูล คำอธิบายที่แทนค่าแล้ว", tur: "Nadirlik, havuz, değerleri yerleştirilmiş açıklama", zhs: "稀有度、卡池、已解析的描述", zht: "稀有度、卡池、已解析的描述" },
  "Starting deck, relics, HP, energy": { eng: "Starting deck, relics, HP, energy", deu: "Startdeck, Relikte, LP, Energie", esp: "Mazo inicial, reliquias, PV, energía", fra: "Deck de départ, reliques, PV, énergie", ita: "Mazzo iniziale, reliquie, PV, energia", jpn: "初期デッキ、レリック、HP、エナジー", kor: "시작 덱, 유물, HP, 에너지", pol: "Talia startowa, relikty, PŻ, energia", ptb: "Baralho inicial, relíquias, HP, energia", rus: "Стартовая колода, реликвии, HP, энергия", spa: "Mazo inicial, reliquias, PV, energía", tha: "เด็คเริ่มต้น เรลิก HP พลังงาน", tur: "Başlangıç destesi, kalıntılar, HP, enerji", zhs: "初始卡组、遗物、生命、能量", zht: "初始卡組、遺物、生命、能量" },
  "Multi-page choices and branching outcomes": { eng: "Multi-page choices and branching outcomes", deu: "Mehrseitige Entscheidungen und verzweigte Ausgänge", esp: "Elecciones de varias páginas y resultados ramificados", fra: "Choix sur plusieurs pages et issues ramifiées", ita: "Scelte su più pagine ed esiti ramificati", jpn: "複数ページの選択肢と分岐する結果", kor: "여러 페이지의 선택지와 분기되는 결과", pol: "Wielostronicowe wybory i rozgałęzione wyniki", ptb: "Escolhas em várias páginas e desfechos ramificados", rus: "Многостраничные выборы и ветвящиеся исходы", spa: "Elecciones de varias páginas y resultados ramificados", tha: "ตัวเลือกหลายหน้าและผลลัพธ์แบบแตกแขนง", tur: "Çok sayfalı seçimler ve dallanan sonuçlar", zhs: "多页选项与分支结果", zht: "多頁選項與分支結果" },
  "Buff / debuff descriptions and stack behaviour": { eng: "Buff / debuff descriptions and stack behaviour", deu: "Buff-/Debuff-Beschreibungen und Stapelverhalten", esp: "Descripciones de buffs/debuffs y comportamiento de acumulación", fra: "Descriptions des buffs/debuffs et comportement de cumul", ita: "Descrizioni di buff/debuff e comportamento di accumulo", jpn: "バフ/デバフの説明とスタックの挙動", kor: "버프/디버프 설명과 중첩 방식", pol: "Opisy buffów/debuffów i zachowanie kumulacji", ptb: "Descrições de buffs/debuffs e comportamento de acúmulo", rus: "Описания баффов/дебаффов и правила накопления", spa: "Descripciones de buffs/debuffs y comportamiento de acumulación", tha: "คำอธิบายบัฟ/ดีบัฟและการซ้อนทับ", tur: "Buff/debuff açıklamaları ve yığılma davranışı", zhs: "增益/减益描述与叠加规则", zht: "增益/減益描述與疊加規則" },
