  "{char} ascended.": { eng: "{char} ascended.", deu: "{char} ist aufgestiegen.", esp: "{char} ascendió.", fra: "{char} a atteint le sommet.", ita: "{char} è asceso.", jpn: "{char}は塔を登り切った。", kor: "{char}이(가) 등반에 성공했다.", pol: "{char} wspiął się na szczyt.", ptb: "{char} ascendeu.", rus: "{char} взошёл на вершину.", spa: "{char} ascendió.", tha: "{char} พิชิตยอดหอคอยแล้ว", tur: "{char} zirveye ulaştı.", zhs: "{char}登顶了。", zht: "{char}登頂了。" },
